package com.yeyamo_mobile.api.moderation_trust_service.interfaces.rest;import java.util.*;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.moderation_trust_service.application.*;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;
@RestController@RequestMapping("/api/v1/trust")@Tag(name="Trust scores")@SecurityRequirement(name="bearerAuth")public class TrustController{private final ModerationService service;public TrustController(ModerationService s){service=s;}@GetMapping("/{subjectId}")public TrustScore get(@PathVariable String subjectId,Authentication auth){boolean privileged=auth.getAuthorities().stream().map(GrantedAuthority::getAuthority).anyMatch(a->a.equals("ROLE_ADMIN")||a.equals("ROLE_SUPER_ADMIN")||a.equals("ROLE_MODERATOR"));if(!privileged&&!auth.getName().equals(subjectId))throw new ModerationException("TRUST_FORBIDDEN","A user can only read their own trust score");return service.trust(subjectId);}}
